    close()
    days = sorted(points)
    return Detection(
        periods=tuple(_group(occurrences, declared)),
        reason=None if evaluated else INSUFFICIENT_HISTORY,
        unit=unit,
        level="median" if params.yearly else "mean",
        points=len(days),
        backfilled=sum(1 for d in days if d in backfilled),
